+      border-radius: 20px;
+      padding: 28px;
+      box-shadow: var(--shadow);
+    }
+
+    h1 {
+      margin: 0 0 12px;
+      font-size: 1.75rem;
+      line-height: 1.2;
+    }
+
+    .intro {
+      margin: 0 0 24px;
+      color: var(--muted);
+      line-height: 1.5;
+    }
+
+    form {
+      display: grid;
+      gap: 20px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 10px;
+      padding: 16px;
+      border-radius: 16px;
+      border: 1px solid #2e3960;
+      background: rgba(255, 255, 255, 0.02);
+    }
+
+    .checkbox-field {
+      display: flex;
+      align-items: flex-start;
+      gap: 12px;
+      line-height: 1.5;
+      font-weight: 600;
+      cursor: pointer;
+    }
+
+    input[type="checkbox"] {
+      width: 18px;
+      height: 18px;
+      margin: 2px 0 0;
+      accent-color: var(--accent);
+      flex: 0 0 auto;
+    }
+
+    .helper-text {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .error-text {
+      margin: 0;
+      color: var(--danger);
+      font-size: 0.95rem;
+    }
+
+    button {
+      border: 0;
+      border-radius: 14px;
+      padding: 14px 18px;
+      background: linear-gradient(180deg, var(--accent-strong), var(--accent));
+      color: #050814;
+      font-size: 1rem;
+      font-weight: 700;
+      cursor: pointer;
+      transition: transform 0.15s ease, filter 0.15s ease;
+    }
+
+    button:hover {
+      filter: brightness(1.05);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible,
+    input[type="checkbox"]:focus-visible {
+      outline: 2px solid transparent;
+      box-shadow: 0 0 0 3px rgba(177, 194, 255, 0.45);
+    }
+
+    .status-message {
+      margin: 0;
+      min-height: 1.5em;
+      color: var(--accent-strong);
+      font-weight: 600;
+    }
+
+    @media (max-width: 480px) {
+      .card {
+        padding: 22px;
+      }
+    }
+
+    @media (forced-colors: active) {
+      body {
+        background: Canvas;
+        color: CanvasText;
+      }
+
+      .card,
+      .form-field {
+        background: Canvas;
+        border-color: ButtonText;
+        box-shadow: none;
+      }
+
+      .skip-link,
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+        border: 1px solid ButtonText;
+      }
+
+      .intro,
+      .helper-text,
+      .status-message,
+      .error-text {
+        color: CanvasText;
+      }
+
+      button:focus-visible,
+      input[type="checkbox"]:focus-visible,
+      .skip-link:focus {
+        outline: 2px solid Highlight;
+        box-shadow: none;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+
+  <main id="main-content">
+    <section class="card" aria-labelledby="form-title">
+      <h1 id="form-title">Terms of use</h1>
+      <p class="intro">Confirm your agreement to continue.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <label class="checkbox-field" for="terms-consent">
+            <input
+              id="terms-consent"
+              name="termsConsent"
+              type="checkbox"
+              required
+              aria-describedby="terms-help terms-error"
+            >
+            <span>I agree to the terms of use <span aria-hidden="true">*</span></span>
+          </label>
+          <p class="helper-text" id="terms-help">Required before submitting.</p>
+          <p class="error-text" id="terms-error" hidden>Please agree to the terms of use.</p>
+        </div>
+
+        <button type="submit">Submit</button>
+        <p class="status-message" id="form-status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById("consent-form");
+    const checkbox = document.getElementById("terms-consent");
+    const errorText = document.getElementById("terms-error");
+    const statusMessage = document.getElementById("form-status");
+
+    const showCheckboxError = () => {
+      checkbox.setAttribute("aria-invalid", "true");
+      errorText.hidden = false;
+      statusMessage.textContent = "";
+    };
+
+    const clearCheckboxError = () => {
+      checkbox.removeAttribute("aria-invalid");
+      errorText.hidden = true;
+    };
+
+    checkbox.addEventListener("invalid", (event) => {
+      event.preventDefault();
+      showCheckboxError();
+    });
+
+    checkbox.addEventListener("change", () => {
+      if (checkbox.checked) {
+        clearCheckboxError();
+      }
+    });
+
+    form.addEventListener("submit", (event) => {
+      if (!form.checkValidity()) {
+        event.preventDefault();
+        showCheckboxError();
+        checkbox.focus();
+        return;
+      }
+
+      event.preventDefault();
+      clearCheckboxError();
+      statusMessage.textContent = "Consent recorded. Thank you.";
+      form.reset();
+    });
+  </script>
+</body>
+</html>
*** End Patch
